const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const uk = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'United Kingdom'));
  const geometry = uk.geometry();

  // Target period: Feb 11-25, 2019
  const targetStart = '2019-02-11';
  const targetEnd = '2019-02-26';

  // Baseline period: Feb 11-25 for years 2000-2012
  const baselineYears = ee.List.sequence(2000, 2012);

  // 2. Data Acquisition - MODIS LST
  const modis = ee.ImageCollection('MODIS/006/MOD11A1')
    .select('LST_Day_1km');

  // Get 2019 data
  let col2019 = modis
    .filterDate(targetStart, targetEnd)
    .filterBounds(geometry);

  const size2019 = col2019.size().getInfo();
  console.log(`2019 Images found: ${size2019}`);

  if (size2019 === 0) {
    console.log('No data for 2019 period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get baseline data (2000-2012)
  const baselineImages = baselineYears.map(function(year) {
    const yearStart = ee.Date.fromYMD(year, 2, 11);
    const yearEnd = yearStart.advance(15, 'day');
    return modis
      .filterDate(yearStart, yearEnd)
      .filterBounds(geometry)
      .mean();
  });

  const baselineCol = ee.ImageCollection(baselineImages);
  const sizeBaseline = baselineCol.size().getInfo();
  console.log(`Baseline year-composites: ${sizeBaseline}`);

  if (sizeBaseline === 0) {
    console.log('No baseline data found.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Create mean composites
  const img2019 = col2019.mean();
  const imgBaseline = baselineCol.mean();

  // Scale factor for MODIS LST: 0.02 (Kelvin)
  const img2019_K = img2019.multiply(0.02);
  const imgBaseline_K = imgBaseline.multiply(0.02);

  // 4. Check pixel counts
  const count2019 = img2019_K.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const countBaseline = imgBaseline_K.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`2019 valid pixels: ${count2019}`);
  console.log(`Baseline valid pixels: ${countBaseline}`);

  if (count2019 === 0 || countBaseline === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate mean temperatures
  const stats2019 = img2019_K.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const statsBaseline = imgBaseline_K.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`2019 mean LST: ${stats2019 ? stats2019.toFixed(2) : 'null'} K`);
  console.log(`Baseline mean LST: ${statsBaseline ? statsBaseline.toFixed(2) : 'null'} K`);

  // 6. Validation & Final Answer
  if (stats2019 === null || statsBaseline === null || 
      isNaN(stats2019) || isNaN(statsBaseline) ||
      stats2019 < 200 || stats2019 > 350 ||
      statsBaseline < 200 || statsBaseline > 350) {
    console.log('Invalid temperature values.');
    console.log('<answer>C3</answer>');
    return;
  }

  const diff = stats2019 - statsBaseline;
  console.log(`Temperature difference: ${diff.toFixed(2)} K`);

  if (stats2019 > statsBaseline) {
    console.log('2019 temperature increased compared to baseline.');
    console.log('<answer>A</answer>');
  } else {
    console.log('2019 temperature did not increase compared to baseline.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
